1	/* ============================================================
2	   Conversation Story — shared page script (interactivity only).
3	   Authored here (source of truth). The build copies this to
4	   out/assets/story.js; both design-prototype.html and every generated page
5	   link it. No event data lives here — it reads everything from the DOM.
6	   ============================================================ */
7	
8	/* ------------------------------------------------------------------
9	   The cards and their detail payloads are static HTML in the page (each card
10	   owns a <template class="detail">); this script just wires up selection,
11	   collapse/reopen, and drag-to-resize.
12	
13	   Selection is driven by the URL fragment, so every event is deep-linkable and
14	   shareable. A generated card's id is the event's ref — `<example>:<line>`, e.g.
15	   #episode-8-before:174 — so a ref pastes straight into the URL. NOTE the colon:
16	   resolve fragments with getElementById (below), never querySelector('#'+id),
17	   which would read the colon as a pseudo-class. Cards are <a href="#..."> anchors,
18	   which also makes them keyboard-focusable and Enter-activatable for free.
19	------------------------------------------------------------------ */
20	const body    = document.body;
21	const sidebar = document.getElementById('sidebar');
22	const dKind   = document.getElementById('d-kind');
23	const dTime   = document.getElementById('d-time');
24	const dBody   = document.getElementById('d-body');
25	const cards   = document.querySelectorAll('.card');
26	const DEFAULT_CARD = document.querySelector('.card.k-assistant');  // so the page is never empty
27	
28	/* the empty-state markup that ships in the sidebar; restored on clear */
29	const EMPTY_HTML = dBody.innerHTML;
30	
31	/* Write path+query+fragment without scrolling or firing hashchange. Wrapped
32	   because some browsers block history writes on file:// URLs — selection and
33	   mode must still work when the URL can't be updated. */
34	function setUrl(url) {
35	  try { history.replaceState(null, '', url); } catch (_) { /* file:// */ }
36	}
37	function setFragment(frag) { setUrl(frag); }
38	
39	/* The sidebar's open/collapsed state is Jess's, not selection's. Only an
40	   explicit open (clicking a card) or an explicit collapse (clicking the active
41	   card, Escape, ×, or advancing a narration beat) moves it. */
42	function collapseSidebar() { body.classList.add('sidebar-collapsed'); }
43	function openSidebar()     { body.classList.remove('sidebar-collapsed'); }
44	
45	/* show a card's detail in the sidebar (pure UI — does not touch the URL).
46	   Also moves real DOM focus to the card: browsers auto-focus whatever element
47	   matches the URL fragment on load, and that focus (and its :focus-visible
48	   outline) otherwise just sits there forever after — completely decoupled
49	   from .active — so narrating past it left a stray outline on the start card
50	   while the real (correctly-moving) selection border was elsewhere. preventScroll
51	   because every caller already handles its own scrolling (or deliberately
52	   doesn't, e.g. the reveal flurry). */
53	function selectCard(card) {
54	  cards.forEach(c => c.classList.remove('active'));
55	  card.classList.add('active');
56	  card.focus({ preventScroll: true });
57	
58	  dKind.textContent = card.querySelector('.gutter .kind').textContent;
59	  dTime.textContent = card.dataset.time + ' UTC';
60	  sidebar.style.setProperty('--kind', getComputedStyle(card).getPropertyValue('--kind'));
61	
62	  dBody.replaceChildren(card.querySelector('template.detail').content.cloneNode(true));
63	  dBody.scrollTop = 0;
64	  updateRelated(card);
65	  showSummaryEditor(card);   // no-op unless the authoring server answered
66	}
67	
68	/* ---- causal-chain highlight ----
69	   The parser links causally-related events (a tool call and its result, a
70	   queue enqueue and its dequeue, the tool call that started a background task
71	   and the notification it eventually delivers) with a shared token in the
72	   card's data-link attribute. Selecting a card lights up every OTHER card
73	   that shares one of its tokens, so the connection is visible without
74	   hunting through the log for a matching id. */
75	function linkTokens(card) {
76	  return (card.dataset.link || '').split(' ').filter(Boolean);
77	}
78	function updateRelated(activeCard) {
79	  const tokens = new Set(linkTokens(activeCard));
80	  cards.forEach(c => {
81	    c.classList.toggle('related', tokens.size > 0 && c !== activeCard &&
82	      linkTokens(c).some(t => tokens.has(t)));
83	  });
84	}
85	
86	/* deselect any card but keep the sidebar open and empty */
87	function clearSelection() {
88	  cards.forEach(c => c.classList.remove('active', 'related'));
89	  dKind.textContent = 'Detail';
90	  dTime.textContent = '';
91	  sidebar.style.setProperty('--kind', 'var(--line-strong)');
92	  dBody.innerHTML = EMPTY_HTML;
93	}
94	
95	/* URL fragment -> selection. Unknown/empty fragment falls back to the default
96	   card so the page is never empty. Used on load and on hashchange; scrolls the
97	   target into view only when arriving via a real fragment (deep link). */
98	function syncFromHash() {
99	  const id = decodeURIComponent(location.hash.slice(1));
100	  const card = id ? document.getElementById(id) : null;
101	  const target = (card && card.classList.contains('card')) ? card : DEFAULT_CARD;
102	  selectCard(target);
103	  if (location.hash) target.scrollIntoView({ block: 'center' });
104	}
105	
106	/* one delegated listener on the container: a click anywhere in a card selects
107	   it and writes its id to the URL (shareable), WITHOUT the native jump-to-anchor
108	   scroll — the detail shows in the sticky sidebar. Modified clicks (⌘/ctrl/…)
109	   fall through so "open link in new tab" still works. */
110	document.getElementById('cards').addEventListener('click', e => {
111	  if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
112	  const card = e.target.closest('.card');
113	  if (!card) return;
114	  e.preventDefault();
115	  if (card.classList.contains('active')) {          // clicking the open card closes it
116	    body.classList.toggle('sidebar-collapsed');
117	    return;
118	  }
119	  setFragment('#' + card.id);
120	  selectCard(card);
121	  openSidebar();
122	});
123	
124	/* deep links, back/forward, and hand-edited fragments */
125	window.addEventListener('hashchange', syncFromHash);
126	
127	/* ---- click-to-copy the event id ----
128	   The copy chips live inside each card's <template> and are cloned into #d-body
129	   on select, so we delegate one listener on the stable #d-body container.
130	   navigator.clipboard needs a secure context (works on localhost/https); the
131	   textarea + execCommand path is the file:// fallback. */
132	function copyText(text) {
133	  if (navigator.clipboard && navigator.clipboard.writeText) {
134	    return navigator.clipboard.writeText(text);
135	  }
136	  return new Promise((resolve, reject) => {
137	    const ta = document.createElement('textarea');
138	    ta.value = text;
139	    ta.style.position = 'fixed'; ta.style.opacity = '0';
140	    document.body.appendChild(ta);
141	    ta.select();
142	    try { document.execCommand('copy') ? resolve() : reject(); }
143	    catch (e) { reject(e); }
144	    finally { document.body.removeChild(ta); }
145	  });
146	}
147	
148	function flashCopied(btn) {
149	  const hint = btn.querySelector('.copy-hint');
150	  const original = hint ? hint.textContent : null;
151	  btn.classList.add('copied');
152	  if (hint) hint.textContent = 'copied!';
153	  clearTimeout(btn._copyTimer);
154	  btn._copyTimer = setTimeout(() => {
155	    btn.classList.remove('copied');
156	    if (hint && original !== null) hint.textContent = original;
157	  }, 1200);
158	}
159	
160	dBody.addEventListener('click', e => {
161	  const btn = e.target.closest('.copy-ref');
162	  if (!btn) return;
163	  copyText(btn.dataset.copy).then(() => flashCopied(btn)).catch(() => {});
164	});
165	
166	/* ============================================================
167	   Modes — explore / edit / narrate.
168	
169	   Exactly one body.mode-* class at a time. The mode is in the URL as
170	   ?mode=narrate so "the talk tab" is bookmarkable alongside the #ref that says
171	   which card; explore is the default and stays out of the URL, so ordinary
172	   links look untouched.
173	
174	   Edit depends on the local authoring server. Its button ships hidden and
175	   un-hides only when GET /api/health answers, so ?mode=edit on the published
176	   site quietly falls back to explore.
177	   ============================================================ */
178	const MODES = ['explore', 'edit', 'narrate'];
179	const modeSwitch = document.getElementById('mode-switch');
180	const modeButtons = Array.from(modeSwitch.querySelectorAll('button'));
181	let mode = 'explore';
182	let editingAvailable = false;
183	/* Set the moment ANY mode change actually takes effect (hotkey, switch click,
184	   Escape, or the health-probe's own `?mode=edit` application below). The
185	   probe reads this before forcing edit mode, so pressing e.g. `n` while the
186	   probe is still in flight wins — the probe won't yank narrate back to edit
187	   out from under a mode Jess already chose. */
188	let modeChangedSinceLoad = false;
189	
190	function setMode(next) {
191	  if (!MODES.includes(next)) return;
192	  if (next === 'edit' && !editingAvailable) return;
193	  if (next === mode) return;
194	  modeChangedSinceLoad = true;
195	  const prev = mode;
196	  mode = next;
197	
198	  MODES.forEach(m => body.classList.toggle('mode-' + m, m === mode));
199	  modeButtons.forEach(b => b.setAttribute('aria-pressed', String(b.dataset.mode === mode)));
200	
201	  const q = new URLSearchParams(location.search);
202	  if (mode === 'explore') q.delete('mode'); else q.set('mode', mode);
203	  const qs = q.toString();
204	  setUrl(location.pathname + (qs ? '?' + qs : '') + location.hash);
205	
206	  onModeChange(prev, mode);
207	}
208	
209	/* Per-mode entry/exit work. Keeping it in one function means setMode never
210	   grows a chain of special cases. */
211	function onModeChange(prev, next) {
212	  if (next === 'narrate') enterNarrate();
213	  else if (prev === 'narrate') exitNarrate();
214	  const active = document.querySelector('.card.active');
215	  if (active) selectCard(active);   // rebuild the detail: the editor is edit-only
216	}
217	
218	modeSwitch.addEventListener('click', e => {
219	  const btn = e.target.closest('button[data-mode]');
220	  if (btn) setMode(btn.dataset.mode);
221	});
222	
223	/* ============================================================
224	   Narrate — reveal the conversation a beat at a time.
225	
226	   `revealed` is a COUNT: cards 0..revealed-1 are shown, and the newest one is
227	   the selection. Keeping it a prefix count (rather than a set) makes stepping
228	   back the same operation as stepping forward, and makes "start from this
229	   card" just an index lookup.
230	
231	   A BEAT is a run of cards ending at the next user/assistant message,
232	   inclusive — one press per conversational turn, with the tool-call flurry
233	   visible on the way. The last beat may have no message at its end; it runs to
234	   the end of the timeline.
235	   ============================================================ */
236	const BEAT_MS = 80;
237	let revealed = 0;
238	let pending = [];
239	
240	function clearPending() { pending.forEach(clearTimeout); pending = []; }
241	function renderReveal() { CARDS.forEach((c, i) => c.classList.toggle('revealed', i < revealed)); }
242	
243	/* count of cards revealed after advancing one beat from `from` */
244	function beatForwardTo(from) {
245	  for (let i = from; i < CARDS.length; i++) if (isMessage(CARDS[i])) return i + 1;
246	  return CARDS.length;
247	}
248	/* count of cards revealed after backing up one beat from `from`; always
249	   un-reveals at least one card, so a half-finished beat backs up to the
250	   previous message rather than sitting still. */
251	function beatBackTo(from) {
252	  for (let i = from - 2; i >= 0; i--) if (isMessage(CARDS[i])) return i + 1;
253	  return 0;
254	}
255	
256	/* Reveal (or hide) up to `target` cards. Going forward the new cards appear one
257	   after another so the flurry reads as a flurry; going back is immediate. */
258	function revealTo(target) {
259	  target = Math.min(CARDS.length, Math.max(0, target));
260	  clearPending();
261	  renderReveal();          // resync the DOM if a previous flurry was cut short
262	  const from = revealed;
263	  if (target === from) return;   // truly a no-op: don't touch the sidebar either
264	  collapseSidebar();       // the stage stays clear unless Jess clicks a card
265	  revealed = target;
266	  if (target < from) { renderReveal(); landOn(); return; }
267	
268	  for (let i = from; i < target; i++) {
269	    const card = CARDS[i], last = i === target - 1;
270	    pending.push(setTimeout(() => {
271	      card.classList.add('revealed');
272	      card.scrollIntoView({ block: 'nearest' });
273	      if (last) landOn();
274	    }, (i - from) * BEAT_MS));
275	  }
276	}
277	
278	/* The newest revealed card is the selection — whatever its kind. That keeps the
279	   URL fragment pointing at where Jess actually is, so a reload resumes. */
280	function landOn() {
281	  if (!revealed) { setFragment(location.pathname + location.search); clearSelection(); return; }
282	  const card = CARDS[revealed - 1];
283	  setFragment('#' + card.id);
284	  selectCard(card);
285	  card.scrollIntoView({ block: 'center', behavior: 'smooth' });
286	}
287	
288	/* Start from the URL fragment if there is one, else from an empty stage.
289	   syncFromHash auto-selects a default card when there's no fragment, so "a card
290	   is active" is NOT the same as "Jess chose a card" — only a real fragment
291	   counts as "start here". */
292	function enterNarrate() {
293	  const frag = decodeURIComponent(location.hash.slice(1));
294	  const at = frag ? CARDS.findIndex(c => c.id === frag) : -1;
295	  clearPending();
296	  revealed = at >= 0 ? at + 1 : 0;
297	  renderReveal();
298	  collapseSidebar();
299	  if (revealed) selectCard(CARDS[revealed - 1]); else clearSelection();
300	}
301	
302	function exitNarrate() {
303	  clearPending();
304	  revealed = 0;
305	  CARDS.forEach(c => c.classList.remove('revealed'));
306	}
307	
308	/* ---- collapse / reopen / clear ---- */
309	document.getElementById('d-close').addEventListener('click', () => body.classList.add('sidebar-collapsed'));
310	document.getElementById('d-clear').addEventListener('click', () => {
311	  setFragment(location.pathname + location.search);   // drop the #<ref>
312	  clearSelection();
313	});
314	/* ---- keyboard ----
315	   Escape peels one layer at a time: an open sidebar first, then the selection.
316	   Ignored while typing, so Escape in the summary box still means "revert the
317	   box" (see showSummaryEditor). */
318	const TYPING = 'input, textarea, select, [contenteditable]';
319	
320	/* Every card in document order, materialized once. */
321	const CARDS = Array.from(cards);
322	const isMessage = c => c.classList.contains('k-user') || c.classList.contains('k-assistant');
323	
324	/* Move the selection by one card, or by one user/assistant message with shift.
325	   Does NOT open the sidebar — that state is Jess's (see collapseSidebar).
326	   Only ever called in explore/edit: the keydown handler's narrate branch
327	   returns before reaching this, so there's no "revealed cards only" case to
328	   filter for here. */
329	function moveSelection(dir, byMessage) {
330	  const list = CARDS;
331	  if (!list.length) return;
332	  const active = document.querySelector('.card.active');
333	  let i = list.indexOf(active);
334	  if (i < 0) i = dir > 0 ? -1 : list.length;
335	  let next = i + dir;
336	  if (byMessage) {
337	    while (next >= 0 && next < list.length && !isMessage(list[next])) next += dir;
338	  }
339	  if (next < 0 || next >= list.length) return;
340	  const card = list[next];
341	  setFragment('#' + card.id);
342	  selectCard(card);
343	  card.scrollIntoView({ block: 'nearest' });
344	}
345	
346	window.addEventListener('keydown', e => {
