409	   local authoring server (bin/serve) answers does an editor appear at the top
410	   of the detail pane. On GitHub Pages the probe 404s and this whole section
411	   stays dark — same JS file, same pages, no build flag.
412	
413	   Saving PUTs {story, ref, summary} and the server rewrites
414	   edits/<story>.yaml, re-runs bin/parse + bin/render, and answers with the
415	   summary that actually landed on disk. So the page updates optimistically
416	   from the SERVER's answer, never from what we typed, and a reload always
417	   agrees with it. Clearing the text reverts to the parser's own summary.
418	   ============================================================ */
419	const STORY = body.dataset.story;
420	
421	/* Rebuild the editor for `card` at the top of the detail pane. Called from
422	   selectCard, so it runs on every selection; a no-op until the probe succeeds. */
423	function showSummaryEditor(card) {
424	  if (!editingAvailable || mode !== 'edit') return;
425	  const summaryEl = card.querySelector('.summary');
426	
427	  const sec = document.createElement('div');
428	  sec.className = 'd-section summary-edit';
429	  sec.innerHTML =
430	    '<h4 class="deco">Summary</h4>' +
431	    '<textarea class="summary-input" rows="2" spellcheck="true"></textarea>' +
432	    '<div class="summary-actions">' +
433	      '<button type="button" class="summary-btn save">Save</button>' +
434	      '<button type="button" class="summary-btn revert">Revert</button>' +
435	      '<span class="summary-status"></span>' +
436	    '</div>';
437	
438	  const input  = sec.querySelector('.summary-input');
439	  const save   = sec.querySelector('.save');
440	  const revert = sec.querySelector('.revert');
441	  const status = sec.querySelector('.summary-status');
442	
443	  const currentText = () => summaryEl.textContent.trim();
444	  const load = () => { input.value = currentText(); autogrow(input); };
445	  load();
446	  revert.disabled = !card.dataset.edited;
447	
448	  /* Send a summary to the server and reconcile the page with its answer.
449	     Empty text means "no override". */
450	  function submit(text) {
451	    // What we're about to throw away, if it was Jess's line and not the
452	    // parser's. Captured before the request so undo has something to restore.
453	    const lost = card.dataset.edited ? currentText() : null;
454	
455	    status.className = 'summary-status';
456	    status.textContent = 'saving…';
457	    return fetch('/api/summary', {
458	      method: 'PUT',
459	      headers: { 'Content-Type': 'application/json' },
460	      body: JSON.stringify({ story: STORY, ref: card.id, summary: text }),
461	    })
462	      .then(r => r.json().then(j => (r.ok ? j : Promise.reject(new Error(j.error || ('HTTP ' + r.status))))))
463	      .then(result => {
464	        applySavedSummary(card, result);
465	        revert.disabled = !result.edited;
466	        status.textContent = result.edited ? 'saved' : 'reverted to generated';
467	        status.classList.add('ok');
