472	        status.classList.add('bad');
473	      });
474	  }
475	
476	  /* A hand-written line just disappeared — Revert dropped it, or a Save wrote
477	     over an older one. The sidecar is in git and the box is right there, but
478	     neither is a *click*, and Revert is one keystroke away from being an
479	     accident. So the confirmation itself carries the way back. It survives only
480	     until the next request or reselect: one level, in-session, which is what
481	     this is protecting against. */
482	  function offerUndo(lost) {
483	    const undo = document.createElement('button');
484	    undo.type = 'button';
485	    undo.className = 'undo';
486	    undo.textContent = 'undo';
487	    undo.addEventListener('click', () => submit(lost).then(load));
488	    status.append(' · ', undo);
489	  }
490	
