# The cards Jess can actually step through — everything EXCEPT cards buried in
# a collapsed subagent block. Those ship collapsed on every generated page, are
# display:none, and story.js's NAV() leaves them out of arrow navigation and
# narrate beats for exactly that reason; a checker that counted them would
# "expect" the selection to land on a card nobody can see.
NAVIGABLE = <<~JS
  (() => {
    const buried = c => {
      for (let w = c.closest('.subactions'); w; w = w.parentElement.closest('.subactions')) {
        const owner = w.previousElementSibling;
        if (owner && owner.classList.contains('collapsed')) return true;
      }
      return false;
    };
    return Array.from(document.querySelectorAll('.card')).filter(c => !buried(c)).map(c => c.id);
  })()
JS

