content.content:
  display: grid;
  grid-template-columns: var(--gutter-w) 1fr;
  gap: 16px; align-items: baseline;
  background: var(--paper-2);
  border: 1px solid var(--line);
  border-left: var(--card-accent) solid var(--kind, var(--ink-faint));
  border-radius: var(--card-radius);
  padding: 13px 18px 13px var(--card-pad);
  margin: 0 0 10px;
  color: inherit; text-decoration: none;   /* cards are <a> anchors */
  cursor: pointer;
  transition: transform .12s ease, box-shadow .12s ease, border-color .12s ease;
}
/* Highlighted = the selected card, PLUS the rest of its causal chain (a tool
   call and its result, a queue enqueue and its dequeue, the call that started a
   background task and the notification it eventually delivers — matched by a
   shared token in data-link, see assets/story.js). One treatment for both:
   being lit up because you clicked this card and being lit up because you
   clicked its sibling should look the same, not subtly different. The leader
   line to the detail pane (.card.active::after) is the one thing only the
   selected card gets — it points at the pane, which shows one event. */
.card.active, .card.related {
  border-color: var(--kind, var(--gold));
  box-shadow: -3px 4px 0 var(--kind, var(--gold));
}
.card:focus-visible {
  outline: 2px solid var(--kind, var(--gold));
  outline-offset: 3px;
}

/* Leader line to the detail pane: an in-flow pseudo-element anchored to the
   card, so it scrolls (and rubber-band bounces) together with the card.
   It runs off the right of the page and is clipped by html{overflow-x:clip};
   the sidebar paints on top of it, so it reads as "going behind" the pane.
   Only shown for the active card. */
.card::after {
  content: ""; position: absolute;
  top: 50%; left: 100%; width: 100vw;
  border-top: 2px dotted var(--kind, var(--gold));
  opacity: 0; pointer-events: none;
}
.card.active::after { opacity: 1; }
/* when the detail pane is collapsed, its card's line has nothing to point to */
body.sidebar-collapsed .card.active::after { opacity: 0; }

